/* eslint-disable react/jsx-props-no-spreading */
import React, { memo, useCallback, useState, useMemo } from 'react'
import { useDispatch, useSelector } from 'react-redux';
import { useForm, Controller } from 'react-hook-form';

import { Form, Modal, Button, Select, Input, message } from 'antd'

import { requestQuote } from 'redux/actions/subscription';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { trackPageViews } from 'redux/actions/trackingReport';

import { ModalWrapper, BottomButtons, TwoRowGrid, FormTitle } from './styles';

// Types and Interfaces
interface FieldConfig {
  required?: boolean;
  visible?: boolean;
  title?: string;
  defaultValue?: string | number;
}

interface FormFieldConfig {
  sessionQuantity?: FieldConfig;
  webSessionQuantity?: FieldConfig;
  customerName?: FieldConfig;
  emailAddress?: FieldConfig;
  companyName?: FieldConfig;
  phoneNumber?: FieldConfig;
  numberOfApps?: FieldConfig;
  numberOfUsers?: FieldConfig;
  message?: FieldConfig;
}

interface FormData {
  sessionQuantity: string;
  webSessionQuantity: string;
  customerName: string;
  emailAddress: string;
  companyName: string;
  phoneNumber: string;
  numberOfApps: string;
  numberOfUsers: string;
  message: string;
}

interface RequestQuoteResponse {
  error?: {
    emailAddress?: string[];
    message?: string;
  };
  success?: boolean;
  message?: string;
}

interface RequestQuoteFormProps {
  onCancel?: () => void;
  showCancelButton?: boolean;
  fieldConfig?: FormFieldConfig;
  onSubmitSuccess?: (data: RequestQuoteResponse) => void;
  onSubmitError?: (error: unknown) => void;
  className?: string;
  showTitle?: boolean;
  triggerTitle?: string;
}

interface ModalProps extends RequestQuoteFormProps {
  setShowPricingModal?: (show: boolean) => void;
  showPricingModal?: boolean;
}

interface RootState {
  currentOrgReducer: {
    orgId: string;
    status: string;
    planType: string;
  };
}

interface RestrictionContextType {
  setTriggerRequestQuote: (trigger: boolean) => void;
  setShowPricingModal: (show: boolean) => void;
  selfServeFlag?: boolean;
  // Add other properties as needed
}

const { Option } = Select;
const { TextArea } = Input;

const sessionRange = [
  { value: 'Less than 50K' },
  { value: '50K - 100K' },
  { value: '100K - 250K' },
  { value: '250K - 500K' },
  { value: '500K - 1M' },
  { value: '1M - 2M' },
  { value: 'More than 2M' }
];


const DEFAULT_FIELD_CONFIG: FormFieldConfig = {
  sessionQuantity: { required: true, visible: true, title: "Estimated monthly sessions", defaultValue: '' },
  webSessionQuantity: { required: false, visible: false, title: "Estimated monthly sessions for web", defaultValue: '' },
  customerName: { required: true, visible: true, title: "Your name", defaultValue: '' },
  emailAddress: { required: true, visible: true, title: "Email address", defaultValue: '' },
  companyName: { required: true, visible: true, title: "Company name", defaultValue: '' },
  phoneNumber: { required: true, visible: true, title: "Phone number", defaultValue: '' },
  numberOfApps: { required: true, visible: true, title: "Number of apps you want to track", defaultValue: '' },
  numberOfUsers: { required: true, visible: true, title: "Number of seats required", defaultValue: '' },
  message: { required: false, visible: true, title: "Message (optional)", defaultValue: '' }
};


const mergeFieldConfig = (defaultConfig: FormFieldConfig, userConfig?: FormFieldConfig): FormFieldConfig => {
  if (!userConfig) return defaultConfig;

  const mergedConfig: FormFieldConfig = {};
  
  // Iterate through all possible field keys
  (Object.keys(defaultConfig) as Array<keyof FormFieldConfig>).forEach(fieldKey => {
    const defaultFieldConfig = defaultConfig[fieldKey];
    const userFieldConfig = userConfig[fieldKey];
    
    if (userFieldConfig) {
      // Merge user config with default config for this field
      mergedConfig[fieldKey] = {
        ...defaultFieldConfig,
        ...userFieldConfig
      };
    } else {
      // Use default config as-is
      mergedConfig[fieldKey] = defaultFieldConfig;
    }
  });

  return mergedConfig;
};


export const RequestQuoteForm = memo((props: RequestQuoteFormProps) => {
  const { 
    onCancel,
    showCancelButton = true,
    fieldConfig: userFieldConfig,
    onSubmitSuccess,
    onSubmitError,
    className = '',
    showTitle = true,
    triggerTitle = 'Request pricing'
  } = props;

  const fieldConfig = useMemo(() => 
    mergeFieldConfig(DEFAULT_FIELD_CONFIG, userFieldConfig), 
    [userFieldConfig]
  );

  const { currentOrgReducer: currentOrg } = useSelector((state: RootState) => state);
  const dispatch = useDispatch();
  const restrictionContext = useRestrictionContext() as RestrictionContextType | null;

  const { orgId } = currentOrg;
  const [loading, setLoading] = useState(false);


  const defaultValues = useMemo(() => ({
    sessionQuantity: fieldConfig.sessionQuantity?.defaultValue as string || '',
    webSessionQuantity: fieldConfig.webSessionQuantity?.defaultValue as string || '',
    customerName: fieldConfig.customerName?.defaultValue as string || '',
    emailAddress: fieldConfig.emailAddress?.defaultValue as string || '',
    companyName: fieldConfig.companyName?.defaultValue as string || '',
    phoneNumber: fieldConfig.phoneNumber?.defaultValue as string || '',
    numberOfApps: fieldConfig.numberOfApps?.defaultValue as string || '',
    numberOfUsers: fieldConfig.numberOfUsers?.defaultValue as string || '',
    message: fieldConfig.message?.defaultValue as string || ''
  }), [fieldConfig]);

  const {
    control,
    handleSubmit,
    reset,
    setError,
    formState: { errors }
  } = useForm<FormData>({
    defaultValues
  });

  const onSubmit = useCallback(async (values: FormData) => {
    setLoading(true);

    try {
      const requestFormData = await dispatch(requestQuote(orgId, values)) as RequestQuoteResponse;
      setLoading(false);

      if (requestFormData.error) {
        if (
          requestFormData.error.emailAddress &&
          requestFormData.error.emailAddress.length
        ) {
          setError('emailAddress', {
            type: 'manual',
            message: 'Please enter valid work email'
          });
        } else {
          if (!requestFormData['success']) {
            message.error(requestFormData['error']?.['message'] || 'An error occurred');
          }
          if (onSubmitError) {
            onSubmitError(requestFormData.error);
          } else if (onCancel) {
            onCancel();
          }
        }
      } else {
        reset();
        if (requestFormData?.message) {
          message.success(requestFormData.message);
        }

        const hasMobileSession = values.sessionQuantity && values.sessionQuantity.trim() !== '';
        const hasWebSession = values.webSessionQuantity && values.webSessionQuantity.trim() !== '';
        const chosenPlatform = (hasMobileSession && hasWebSession) ? 'Mobile, Web' : ''; // * for single platform select we don't send any value for now
        const selfServeStatus = restrictionContext?.selfServeFlag ? 'enabled' : 'disabled';

        dispatch(trackPageViews(null, {
          eventName: 'wa_pricing_request_submitted',
          track_type: 'event',
          eventProperty: {
              self_serve_status: selfServeStatus,
              chosen_platform: chosenPlatform,
            }
        }));

        if (onSubmitSuccess) {
          onSubmitSuccess(requestFormData);
        } else if (onCancel) {
          onCancel();
        }
      }
    } catch (err) {
      setLoading(false);
      if (onSubmitError) {
        onSubmitError(err);
      }
    }
  }, [dispatch, orgId, setError, onSubmitError, onCancel, reset, restrictionContext?.selfServeFlag, onSubmitSuccess]);

  // eslint-disable-next-line no-shadow
  const renderField = (fieldName: keyof FormFieldConfig, fieldConfig: FieldConfig | undefined, renderFunction: () => React.ReactElement) => {
    if (!fieldConfig?.visible) return null;
    return renderFunction();
  };

  const getValidationRules = (fieldName: keyof FormFieldConfig, customRules: Record<string, unknown> = {}) => {
    const config = fieldConfig[fieldName];
    const rules = { ...customRules };
    
    if (config?.required) {
      rules.required = customRules.required || `Please enter ${fieldName.replace(/([A-Z])/g, ' $1').toLowerCase()}`;
    }
    
    return rules;
  };

  return (
    <ModalWrapper>
        <div className={className}>
        {showTitle && <FormTitle>Request pricing</FormTitle>}
        <Form layout="vertical" onFinish={handleSubmit(onSubmit)}>
            {renderField('sessionQuantity', fieldConfig.sessionQuantity, () => (
            <Form.Item
                label={fieldConfig.sessionQuantity?.title}
                validateStatus={errors.sessionQuantity ? 'error' : ''}
                help={errors.sessionQuantity?.message}
            >
                <Controller
                name="sessionQuantity"
                control={control}
                rules={getValidationRules('sessionQuantity', {
                    required: fieldConfig.sessionQuantity?.required ? 'Please select number of monthly sessions' : false
                })}
                render={({ field }) => (
                    <Select
                    {...field}
                    getPopupContainer={(node) => node.parentNode}
                    showSearch
                    placeholder="Select number of sessions"
                    dropdownClassName="modal-dropdown"
                    >
                    {sessionRange.map((range) => (
                        <Option key={range.value} value={range.value}>
                        {range.value}
                        </Option>
                    ))}
                    </Select>
                )}
                />
            </Form.Item>
            ))}

            {renderField('webSessionQuantity', fieldConfig.webSessionQuantity, () => (
            <Form.Item
                label={fieldConfig.webSessionQuantity?.title}
                validateStatus={errors.webSessionQuantity ? 'error' : ''}
                help={errors.webSessionQuantity?.message}
            >
                <Controller
                name="webSessionQuantity"
                control={control}
                rules={getValidationRules('webSessionQuantity', {
                    required: fieldConfig.webSessionQuantity?.required ? 'Please select number of web sessions' : false
                })}
                render={({ field }) => (
                    <Select
                    {...field}
                    showSearch
                    getPopupContainer={(node) => node.parentNode}
                    placeholder="Select number of web sessions"
                    dropdownClassName="modal-dropdown"
                    >
                    {sessionRange.map((range) => (
                        <Option key={range.value} value={range.value}>
                        {range.value}
                        </Option>
                    ))}
                    </Select>
                )}
                />
            </Form.Item>
            ))}

            <TwoRowGrid>
            {renderField('customerName', fieldConfig.customerName, () => (
                <Form.Item
                label={fieldConfig.customerName?.title}
                validateStatus={errors.customerName ? 'error' : ''}
                help={errors.customerName?.message}
                >
                <Controller
                    name="customerName"
                    control={control}
                    rules={getValidationRules('customerName', {
                    required: fieldConfig.customerName?.required ? 'Please enter your name' : false
                    })}
                    render={({ field }) => (
                    <Input
                        {...field}
                        maxLength={255}
                        placeholder="Enter your name"
                    />
                    )}
                />
                </Form.Item>
            ))}

            {renderField('emailAddress', fieldConfig.emailAddress, () => (
                <Form.Item
                label={fieldConfig.emailAddress?.title}
                validateStatus={errors.emailAddress ? 'error' : ''}
                help={errors.emailAddress?.message}
                >
                <Controller
                    name="emailAddress"
                    control={control}
                    rules={getValidationRules('emailAddress', {
                    required: fieldConfig.emailAddress?.required ? 'Please enter your email address' : false,
                    pattern: {
                        value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i,
                        message: 'Please enter a valid email address'
                    }
                    })}
                    render={({ field }) => (
                    <Input
                        {...field}
                        type="email"
                        placeholder="Enter your work email"
                    />
                    )}
                />
                </Form.Item>
            ))}
            </TwoRowGrid>

            <TwoRowGrid>
            {renderField('companyName', fieldConfig.companyName, () => (
                <Form.Item
                label={fieldConfig.companyName?.title}
                validateStatus={errors.companyName ? 'error' : ''}
                help={errors.companyName?.message}
                >
                <Controller
                    name="companyName"
                    control={control}
                    rules={getValidationRules('companyName', {
                    required: fieldConfig.companyName?.required ? 'Please enter your company name' : false
                    })}
                    render={({ field }) => (
                    <Input
                        {...field}
                        placeholder="Enter company name"
                    />
                    )}
                />
                </Form.Item>
            ))}

            {renderField('phoneNumber', fieldConfig.phoneNumber, () => (
                <Form.Item
                label={fieldConfig.phoneNumber?.title}
                validateStatus={errors.phoneNumber ? 'error' : ''}
                help={errors.phoneNumber?.message}
                >
                <Controller
                    name="phoneNumber"
                    control={control}
                    rules={getValidationRules('phoneNumber', {
                    required: fieldConfig.phoneNumber?.required ? 'Please enter your phone number' : false
                    })}
                    render={({ field }) => (
                    <Input
                        {...field}
                        placeholder="Enter phone number"
                    />
                    )}
                />
                </Form.Item>
            ))}
            </TwoRowGrid>

            <TwoRowGrid>
            {renderField('numberOfApps', fieldConfig.numberOfApps, () => (
                <Form.Item
                label={fieldConfig.numberOfApps?.title}
                validateStatus={errors.numberOfApps ? 'error' : ''}
                help={errors.numberOfApps?.message}
                >
                <Controller
                    name="numberOfApps"
                    control={control}
                    rules={getValidationRules('numberOfApps', {
                    required: fieldConfig.numberOfApps?.required ? 'Please enter number of apps you want to track in UXCam' : false,
                    pattern: {
                        value: /^[1-9]\d*$/,
                        message: 'Please enter a valid number greater than 0'
                    }
                    })}
                    render={({ field }) => (
                    <Input
                        {...field}
                        placeholder="Enter number of apps"
                        style={{ width: '100%' }}
                    />
                    )}
                />
                </Form.Item>
            ))}

            {renderField('numberOfUsers', fieldConfig.numberOfUsers, () => (
                <Form.Item
                label={fieldConfig.numberOfUsers?.title}
                validateStatus={errors.numberOfUsers ? 'error' : ''}
                help={errors.numberOfUsers?.message}
                >
                <Controller
                    name="numberOfUsers"
                    control={control}
                    rules={getValidationRules('numberOfUsers', {
                    required: fieldConfig.numberOfUsers?.required ? 'Please enter number of seats required' : false,
                    pattern: {
                        value: /^[1-9]\d*$/,
                        message: 'Please enter a valid number greater than 0'
                    }
                    })}
                    render={({ field }) => (
                    <Input
                        {...field}
                        placeholder="Enter number of seats"
                        style={{ width: '100%' }}
                    />
                    )}
                />
                </Form.Item>
            ))}
            </TwoRowGrid>

            {renderField('message', fieldConfig.message, () => (
            <Form.Item
                label={fieldConfig.message?.title}
                validateStatus={errors.message ? 'error' : ''}
                help={errors.message?.message}
            >
                <Controller
                name="message"
                control={control}
                rules={getValidationRules('message')}
                render={({ field }) => (
                    <TextArea
                    {...field}
                    rows={4}
                    placeholder="Enter your message"
                    style={{fontSize: '12px'}}
                    />
                )}
                />
            </Form.Item>
            ))}

            <BottomButtons>
            {showCancelButton && (
                <Button key='button' type='link' onClick={onCancel}>
                Cancel
                </Button>
            )}
            <Button
                key="submit"
                type='primary'
                className="ant-btn"
                loading={loading}
                htmlType="submit"
            > 
                {triggerTitle}
            </Button>
            </BottomButtons>
        </Form>
        </div>
    </ModalWrapper>
  );
});

const NewRequestQuoteFormModal = memo((props: ModalProps) => {
  const { 
    setShowPricingModal, 
    showPricingModal,
    fieldConfig,
    ...restProps 
  } = props;

  const { currentOrgReducer: currentOrg } = useSelector((state: RootState) => state);
  const { status, planType } = currentOrg;
  const restrictionContext = useRestrictionContext() as RestrictionContextType | null;
  

  const handleCancel = useCallback(() => {
   const setTriggerRequestQuote = restrictionContext?.setTriggerRequestQuote;
    if(planType === "trial" && status === "Expired"){
        setTriggerRequestQuote?.(false)
    }else{
        setShowPricingModal?.(false)
        setTriggerRequestQuote?.(false);
    }
  }, [planType, restrictionContext?.setTriggerRequestQuote, setShowPricingModal, status]);

  return (
    <Modal
      wrapClassName='filters-locked-modal request-pricing-modal'
      visible={showPricingModal}
      closable={false}
      footer={null}
      onCancel={handleCancel}
      maskStyle={{ zIndex: '99998', background: 'rgba(22, 30, 53, 0.3)' }}
      getContainer={() => document.body.querySelector('.ant-layout-content') as HTMLElement}
    >
        <RequestQuoteForm
          key="request-quote-form"
          {...restProps}
          onCancel={handleCancel}
          fieldConfig={fieldConfig}
        />
    </Modal>
  );
});

export default NewRequestQuoteFormModal;