import {
  CURRENT_SUBSCRIPTION,
  PAYMENT_HISTORY_TABLE,
  ORG_AVAILABLE_PLANS,
  QUERY_PLAN_CHANGE,
  ORG_APP_TEAM_LIST,
  CURRENT_ORGANIZATION,
  INVOICE_RECEIPT,
  SESSION_USAGE,
  WEB_SESSION_USAGE,
} from 'types'

import SubscriptionApi from 'services/subscriptionApi'
import {getCsrf, getErrorHandle, postErrorHandle} from './common'

export const updateCurrentSubscription = data => ({
    type: CURRENT_SUBSCRIPTION,
    data
  })

export const updateActiveSubscription = data => ({
    type: CURRENT_ORGANIZATION,
    data
  })

export const updateOrgAvailablePlans = data => ({
    type: ORG_AVAILABLE_PLANS,
    data
  })

export const updatePaymentHistory = data => ({
    type: PAYMENT_HISTORY_TABLE,
    data
  })
export const updateQueryPlanChange = data => ({
    type: QUERY_PLAN_CHANGE,
    data
  })

export const updateOrgAppTeamList = data => ({
    type: ORG_APP_TEAM_LIST,
    data
  })

export const updateInvoiceReciept = data => ({
    type: INVOICE_RECEIPT,
    data
  })

export const sessionUsageLimit = data =>({
  type: SESSION_USAGE,
  data
})

export const webSessionUsageLimit = data =>({
  type: WEB_SESSION_USAGE,
  data
})

export const resetSubscription = () => (dispatch) => {
  dispatch(updateCurrentSubscription({}))
  // dispatch(updateSubscriptionPlanList([]));
  dispatch(updatePaymentHistory({paymentHistory: [], pagination: {}, loading: true}))
  dispatch(updateOrgAvailablePlans({}))
}
export const getClientSubscriptionToken = data => (dispatch, getState) => SubscriptionApi.getClientSubscriptionToken(data)
.then(res => res.data.data.clientToken).catch(error => postErrorHandle(dispatch, undefined, error.response, {orgId: getState().urlReducer.org}))

export const getCurrentSubscription = (data) => (dispatch) => SubscriptionApi.getCurrentSubscription(data)
  .then(res => dispatch(updateCurrentSubscription(res.data.data))).catch(error => getErrorHandle(dispatch, updateCurrentSubscription, error))

export const getActiveSubscription = (orgId) => (dispatch, getState) => SubscriptionApi.getActiveSubscription(orgId)
    .then((res) => {
      const state = getState()
      const activeOrgId =
        state.urlReducer?.org ||
        state.urlReducer?.orgId ||
        state.currentAppReducer?.orgId
      if (!orgId || !activeOrgId || String(activeOrgId) === String(orgId)) {
        dispatch(updateActiveSubscription(res.data.data))
      }
      return res.data
    })
    .catch((error) => { getErrorHandle(dispatch, updateActiveSubscription, error.response); return error.response })
