export const getOrgAvailablePlans = data => (dispatch) => SubscriptionApi.getOrgAvailablePlans(data)
.then(res => dispatch(updateOrgAvailablePlans(res.data.data))).catch(error => getErrorHandle(dispatch, updateOrgAvailablePlans, error))

export const getPaymentHistory = (orgId, page, csrf) => (dispatch) => {
  dispatch(updatePaymentHistory({paymentHistory: [], pagination: {}, loading: true}))
  SubscriptionApi.getPaymentHistory(orgId, page, csrf).then(res => dispatch(updatePaymentHistory({paymentHistory: res.data.data.paymentHistory, pagination: res.data.data.pagination, loading: false}))).catch(error => getErrorHandle(dispatch, updatePaymentHistory, error))
}

export const getQueryPlanChange = (orgId, planName, csrf) => (dispatch) => SubscriptionApi.getQueryPlanChange(orgId, planName, csrf)
.then(res => dispatch(updateQueryPlanChange(res.data.data))).catch(error => error)

export const updatePlan = (orgId, planCode, nonce, csrf, app, team) => () => SubscriptionApi.updatePlan(orgId, planCode, nonce, csrf, app, team)
.then(res => res.data.data).catch(error => error)

export const changePayment = (orgId, nonce, csrf) => (dispatch, getState) => SubscriptionApi.changePayment(orgId, nonce, csrf)
.then(res => {
  const stateData = {...getState().currentSubscriptionReducer}
  stateData.method = res.data.data
  dispatch(updateCurrentSubscription(stateData))
  return res
}).catch(error => error)

export const getOrgAppTeamList = (orgId) => (dispatch) => SubscriptionApi.getOrgAppTeam(orgId)
.then(res => dispatch(updateOrgAppTeamList(res.data.data))).catch(error => getErrorHandle(dispatch, updateOrgAppTeamList, error))

export const getInvoiceReciept = (orgId, id, csrf) => (dispatch) => SubscriptionApi.getInvoice(orgId, id, csrf)
.then(res => dispatch(updateInvoiceReciept(res.data.data))).catch(error => getErrorHandle(dispatch, updateInvoiceReciept, error))

export const updateInvoice = (orgId, data) => (dispatch, getState) => {
  return SubscriptionApi.updateInvoiceRecipientsAndAddress(orgId, data)
    .then(res => {
      const stateData = {...getState().currentSubscriptionReducer}

      stateData.invoice.invoiceRecipients = res.data.data.organization.invoiceRecipients ? [...res.data.data.organization.invoiceRecipients] : null
      stateData.invoice.invoiceAddress = res.data.data.organization.invoiceAddress
      dispatch(updateCurrentSubscription(stateData))
      return res.data;
    }).catch(error => {
      postErrorHandle(dispatch, undefined, error.response, {orgId: getState().urlReducer.org})
       return error?.response
    })

}

export const getQueryPremiumPlan = (orgId, planName, csrf) => (dispatch, getState) => SubscriptionApi.getQueryPremiumPlan(orgId, planName, csrf)
    .then(res => dispatch(updateQueryPlanChange(res.data.data))).catch(error => postErrorHandle(dispatch, undefined, error.response, {orgId: getState().urlReducer.org}))

export const requestQuote = (orgId, data) => (dispatch, getState) => {
  orgId = orgId || getState().currentOrgReducer.orgId
  return SubscriptionApi.postRequestQuote(orgId, data)
    .then(res => res.data.data)
    .catch(error => postErrorHandle(dispatch, undefined, error.response, { orgId }))
}

export const retryPayment = (orgId) => () => SubscriptionApi.retryPayment(orgId)
    .then(res => res.data.data).catch(error => error.response.data)

export const getSessionUsage = (orgId) => (dispatch) =>SubscriptionApi.getSessionUsage(orgId)
      .then(res => {
        dispatch(sessionUsageLimit(res.data.data))
        return res.data
      })
      .catch(error => getErrorHandle(dispatch, sessionUsageLimit, error))


export const updateSessionUsage = (orgId, data) => async (dispatch) => {
  const csrf = await dispatch(getCsrf())
  data['_csrf'] = csrf
  return SubscriptionApi.updateSessionUsage(orgId, data)
      .then(res => {
            if (res?.data?.success) {
              dispatch(sessionUsageLimit(res?.data?.data))
              return res.data
            }
          }
      ).catch(error => getErrorHandle(dispatch, sessionUsageLimit, error))
}

